// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Benchmark: run a URL list through the ladder, report cost per good page
// Flo: read list (L<level> <url>) > dry-run prints plan and worst case > live fetches each URL > tally per tier and vendor > text table > append dated section to a file
// I/O: --list file (caller) > table on stdout, optional section in --out file; dry-run unless --live
// ===================================================================
const std = @import("std"); const cx = @import("ct-ctrl-ctxz.zig"); const runz = @import("ct-ctrl-runz.zig"); const ladd = @import("ru-tier-ladd.zig"); const pipe = @import("ru-page-fetc.zig"); const brwx = @import("ct-ctrl-brow.zig");
pub const Item = struct { level: u8, urlz: []const u8 };
pub const Res = struct { level: u8, urlz: []const u8, good: bool, tier: i64, vend: []const u8, cred: u32, micr: u64, errz: []const u8 };
pub fn listRead(aren: std.mem.Allocator, text: []const u8) ![]const Item { var list: std.ArrayList(Item) = .empty; var itr = std.mem.splitScalar(u8, text, '\n'); while (itr.next()) |raw| { const ln = std.mem.trim(u8, raw, " \t\r"); if (ln.len == 0 or ln[0] == '#') continue; const sp = std.mem.findScalar(u8, ln, ' ') orelse return error.BadUsage; if (ln[0] != 'L' and ln[0] != 'l') return error.BadUsage; const lv = std.fmt.parseInt(u8, ln[1..sp], 10) catch return error.BadUsage; if (lv < 1 or lv > 9) return error.BadUsage; try list.append(aren, .{ .level = lv, .urlz = std.mem.trim(u8, ln[sp + 1 ..], " \t") }); } return list.toOwnedSlice(aren); }
pub fn benchRun(aren: std.mem.Allocator, lad: *ladd.Ladd, items: []const Item) ![]const Res { const outp = try aren.alloc(Res, items.len); for (items, 0..) |it, ix| { if (lad.sess) |ss| { if (ix % 8 == 7) ss.reset(); } if (ladd.laddFetc(lad, aren, it.urlz)) |oc| { const good = std.mem.eql(u8, oc.stat, "new") or std.mem.eql(u8, oc.stat, "same") or std.mem.eql(u8, oc.stat, "notm"); outp[ix] = .{ .level = it.level, .urlz = it.urlz, .good = good, .tier = oc.tier, .vend = oc.vend, .cred = oc.cred, .micr = oc.micr, .errz = if (good) "" else oc.stat }; } else |err| { outp[ix] = .{ .level = it.level, .urlz = it.urlz, .good = false, .tier = 0, .vend = "", .cred = 0, .micr = 0, .errz = @errorName(err) }; } } return outp; }
pub fn benchText(aren: std.mem.Allocator, res: []const Res, date: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; try outp.print(aren, "## Bench {s}\n| Level | URLs | Good | Hit rate | Cost per good page (micro-USD) |\n|---|---|---|---|---|\n", .{date}); var lv: u8 = 1; while (lv <= 9) : (lv += 1) { var tot: u32 = 0; var gd: u32 = 0; var mic: u64 = 0; for (res) |rs| { if (rs.level != lv) continue; tot += 1; mic += rs.micr; if (rs.good) gd += 1; } if (tot == 0) continue; try outp.print(aren, "| L{d} | {d} | {d} | {d}% | {d} |\n", .{ lv, tot, gd, gd * 100 / tot, if (gd > 0) mic / gd else 0 }); } try outp.appendSlice(aren, "| Tier / vendor | Good | Credits | Micro-USD |\n|---|---|---|---|\n"); const keys = [_][]const u8{ "", "deco", "zenr", "brig", "brow" }; var tier: i64 = 1; while (tier <= 4) : (tier += 1) { for (keys) |ky| { var gd: u32 = 0; var cr: u32 = 0; var mic: u64 = 0; for (res) |rs| { if (!rs.good or rs.tier != tier or !std.mem.eql(u8, rs.vend, ky)) continue; gd += 1; cr += rs.cred; mic += rs.micr; } if (gd == 0) continue; try outp.print(aren, "| T{d} {s} | {d} | {d} | {d} |\n", .{ tier, if (ky.len == 0) "own" else ky, gd, cr, mic }); } } for (res) |rs| { if (!rs.good) try outp.print(aren, "- failed L{d}: {s} ({s})\n", .{ rs.level, rs.urlz, rs.errz }); } return outp.toOwnedSlice(aren); }
fn dayText(aren: std.mem.Allocator, now: i64) ![]u8 { const es = std.time.epoch.EpochSeconds{ .secs = @intCast(@divFloor(now, 1000)) }; const yd = es.getEpochDay().calculateYearDay(); const md = yd.calculateMonthDay(); return std.fmt.allocPrint(aren, "{d}-{d:0>2}-{d:0>2}", .{ yd.year, @intFromEnum(md.month), md.day_index + 1 }); }
pub fn runBench(ctx: *const cx.Ctx) !u8 { if (ctx.args.list.len == 0) return error.BadUsage; const txt = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, ctx.args.list, ctx.allo, .limited(1 << 20)) catch return error.BadUsage; const items = try listRead(ctx.allo, txt); var per = @as([10]u32, @splat(0)); for (items) |it| per[it.level] += 1; if (!ctx.args.live) { const est = runz.estWorst(ctx.conf, ctx.args.geoz); var thin: u32 = 0; for (per[1..]) |cn| { if (cn == 1) thin += 1; } try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "dry-run | bench {d} URLs | worst case {d} credits ({d} micro-USD) per URL | {d} levels have only 1 URL (use 2+) | add --live to run", .{ items.len, est.cred, est.micr, thin })); return 0; } var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); var real = try cx.realMake(ctx); var brw = try brwx.brwMake(ctx, ""); defer if (brw) |*bwz| bwz.deinit(); var lad: ladd.Ladd = .{ .gpaz = ctx.init.gpa, .iozz = ctx.iozz, .conf = ctx.conf, .dbzz = &dbzz, .dirz = ctx.dirz, .back = real.backend(), .go = ctx.args.forc, .geoz = ctx.args.geoz, .sess = if (brw) |*bwz| bwz else null }; const res = try benchRun(ctx.allo, &lad, items); const sec = try benchText(ctx.allo, res, try dayText(ctx.allo, pipe.nowMs(ctx.iozz))); try cx.outz(ctx, sec); if (ctx.args.outz.len > 0) { const old = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, ctx.args.outz, ctx.allo, .limited(4 << 20)) catch ""; const all = try std.fmt.allocPrint(ctx.allo, "{s}\n{s}", .{ old, sec }); try std.Io.Dir.cwd().writeFile(ctx.iozz, .{ .sub_path = ctx.args.outz, .data = all }); } return 0; }
